// qimembed applies Quantization Index Modulation to embed one bit.
func qimembed(c float64, bit int, delta float64) float64 {
	base := math.Floor(c/delta) * delta
	if bit == 0 {
		return base + delta/4
	}
	return base + 3*delta/4
}

// qimExtract recovers a bit from a QIM-quantized coefficient.
func qimExtract(c float64, delta float64) int {
	base := math.Floor(c/delta) * delta
	remainder := c - base
	if remainder < delta/2 {
		return 0
	}
	return 1
}

